(()=>{
 const en=document.documentElement.lang==='en',t=(a,b)=>en?b:a,$=id=>document.getElementById(id);
 const old=document.querySelector('main.shell');const app=document.createElement('div');app.className='gg-app';app.innerHTML=`<aside class="gg-sidebar"><a class="gg-logo" href="#/home"><span class="gg-symbol">g↗</span>GreenGo<span class="gg-period">.</span></a><p class="gg-school">BIRMINGHAM · CAMPUS EDITION</p><nav class="gg-nav" aria-label="${t('主导航','Main navigation')}"></nav><div class="gg-sidebar-bottom"><span class="gg-dot"></span> ${t('从课表到教室','From timetable to classroom')}<p>${t('研究交互原型','INTERACTIVE RESEARCH PROTOTYPE')}</p></div></aside><main class="gg-main"><header class="gg-header"><div><span class="gg-overline">GREENGO / <span id="ggBreadcrumb"></span></span><p id="ggDate"></p></div><div class="gg-header-right"><span class="gg-campus-chip">EDGBASTON</span><a href="${en?'index.html':'en.html'}">${en?'中文':'English'} ↗</a></div></header><div id="ggPages"></div></main>`;document.body.prepend(app);
 const icons={home:'◷',classes:'▦',journey:'↗',settings:'☷'};
 const names={home:t('今日到达','Today'),classes:t('课程日历','Classes'),journey:t('完整行程','Journey'),settings:t('提醒与偏好','Preferences')};const pages={};
 Object.entries(names).forEach(([id,name])=>{const a=document.createElement('a');a.href='#/'+id;a.dataset.page=id;a.innerHTML=`<span>${icons[id]}</span>${name}<small>↗</small>`;app.querySelector('.gg-nav').append(a);const p=document.createElement('section');p.id='page-'+id;p.className='gg-page';p.setAttribute('aria-label',name);pages[id]=p;$('ggPages').append(p);});
 pages.home.innerHTML=`<div class="gg-intro"><p class="gg-overline">LESS SEARCHING. MORE ARRIVING.</p><h1>${t('下一节课。<br><em>从容抵达。</em>','Next class.<br><em>A calmer arrival.</em>')}</h1><p>${t('课程、交通与校园最后一段路，<br>在同一个计划里。','Class, commute and the final campus walk.<br>One connected plan.')}</p></div><div class="gg-home-grid"><article class="gg-next"><div class="gg-card-top"><span>${t('下一段旅程','NEXT JOURNEY')}</span><span class="gg-tag">${t('课程驱动','CLASS-LED')}</span></div><div id="ggNextSummary"><span class="gg-empty-icon">↗</span><h2>${t('先添加一节课','Start with a class')}</h2><p>${t('输入时间与地点，即可连接完整行程。','Add a time and place to connect the journey.')}</p></div><a class="gg-cta" href="#/classes">${t('管理课程','Manage classes')} <span>→</span></a></article><article class="gg-route-art"><div class="gg-art-caption">DOOR TO CLASSROOM</div><div class="gg-line-path"></div><span class="gg-node gg-n1">A</span><span class="gg-node gg-n2">↗</span><span class="gg-node gg-n3">B</span><p class="gg-art-start">${t('出发','START')}</p><p class="gg-art-end">${t('教室','CLASSROOM')}</p><span class="gg-art-note">${t('每一段，都有衔接。','Every leg, connected.')}</span></article></div><div class="gg-quick"><a href="#/classes"><b>01</b><span>${t('安排课程','Set the class')}</span>＋</a><a href="#/journey"><b>02</b><span>${t('查看完整行程','Connect the journey')}</span>↗</a><a href="#/settings"><b>03</b><span>${t('开启主动建议','Enable proactive advice')}</span>→</a></div><section class="gg-monitor"><div><p class="gg-overline">A TIMELY NUDGE</p><h2>${t('重要变化，适时提示。','A timely nudge, when it matters.')}</h2><p>${t('出发时间与天气变化提示仅在页面运行时检查。','Departure and weather checks run only while this page is open.')}</p></div><a class="outline" href="#/settings">${t('设置提醒','Reminder settings')} →</a></section><div id="ggHomeAlert"></div>`;
 const courseTitle=document.createElement('div');courseTitle.className='gg-page-title';courseTitle.innerHTML=`<p class="gg-overline">01 / CLASS FIRST</p><h1>${t('课程，作为起点。','A class to start from.')}</h1><p>${t('安排一次，连接每一段到达。','Set the time and place. Connect the rest.')}</p>`;pages.classes.append(courseTitle,$('classes'));
 const form=$('classForm');const formWrap=document.createElement('details');formWrap.className='gg-form-drawer';const sum=document.createElement('summary');sum.textContent=t('＋ 添加或编辑课程','＋ Add or edit a class');form.before(formWrap);formWrap.append(sum,form);form.addEventListener('focusin',()=>formWrap.open=true);$('classList').addEventListener('click',e=>{if(e.target.textContent===t('编辑本次','Edit occurrence'))formWrap.open=true;});
 pages.journey.innerHTML=`<div class="gg-page-title"><p class="gg-overline">02 / CONNECT THE DOTS</p><h1>${t('一段完整的到达。','One connected journey.')}</h1><p>${t('概览、校外通勤、校园步行与教室。','Overview, travel, campus and classroom.')}</p></div>`;pages.journey.append($('arrivalFlow'));
 pages.settings.innerHTML=`<div class="gg-page-title"><p class="gg-overline">03 / ON THE RIGHT TERMS</p><h1>${t('提醒，有分寸。','A nudge. On the right terms.')}</h1><p>${t('主动建议可启用、稍后或关闭。','Enable, snooze or switch off proactive advice.')}</p></div>`;pages.settings.append($('proactive'));
 const scope=document.createElement('details');scope.className='gg-data';scope.innerHTML=`<summary>${t('数据与原型边界','Data and prototype scope')} ↗</summary>`;const status=document.querySelector('.data-status');if(status)scope.append(status);const oldScope=old.querySelector('footer')?.previousElementSibling;if(oldScope)scope.append(oldScope);pages.settings.append(scope);old.hidden=true;
 const dateFmt=new Intl.DateTimeFormat(en?'en-GB':'zh-CN',{timeZone:'Europe/London',weekday:'long',day:'numeric',month:'long'});$('ggDate').textContent=dateFmt.format(new Date());
 const labels={overview:t('概览','Overview'),outside:t('通勤与天气','Travel & weather'),campus:t('校园步行','Campus'),room:t('教室','Room')};Array.from($('arrivalFlow').querySelector('nav').children).forEach((b,i)=>{b.textContent=`0${i+1}  `+Object.values(labels)[i];});
 function show(){const hash=location.hash;let id=hash.startsWith('#/')?hash.slice(2).split('?')[0]:hash==='#proactive'?'settings':hash==='#map'?'journey':hash==='#classes'?'classes':'home';if(!pages[id])id='home';for(const [name,p]of Object.entries(pages))p.hidden=name!==id;app.querySelectorAll('.gg-nav a').forEach(a=>a.setAttribute('aria-current',a.dataset.page===id?'page':'false'));$('ggBreadcrumb').textContent=names[id];document.title='GreenGo · '+names[id];window.scrollTo({top:0,behavior:'instant'});if(id==='journey'){window.dispatchEvent(new Event('resize'));}}
 window.addEventListener('hashchange',show);show();
 window.addEventListener('greengo:class-selected',e=>{const c=e.detail;const box=$('ggNextSummary');box.replaceChildren();const name=document.createElement('h2');name.textContent=c.title;const time=document.createElement('p');time.className='gg-class-time';time.textContent=c.time;const info=document.createElement('p');info.textContent=`${c.day} · ${c.building} · ${c.room||t('教室待填写','Room pending')}`;box.append(time,name,info);location.hash='/journey';});
 const alert=$('reminderAlert');new MutationObserver(()=>{const box=$('ggHomeAlert');box.replaceChildren();if(!alert.hidden){const card=document.createElement('div');card.className='gg-alert-card';const h=document.createElement('h3');h.textContent=$('alertTitle').textContent;const p=document.createElement('p');p.textContent=$('alertText').textContent;const a=document.createElement('a');a.href='#/settings';a.textContent=t('查看并处理提醒 →','Review reminder →');card.append(h,p,a);box.append(card);}}).observe(alert,{attributes:true,childList:true,subtree:true});
 $('reviewJourney').addEventListener('click',()=>{location.hash='/journey';});$('clearClasses').addEventListener('click',()=>{$('ggNextSummary').innerHTML=`<h2>${t('尚无课程','No classes yet')}</h2><p>${t('添加一节课开始。','Add a class to begin.')}</p>`;});
})();
